mapper.select:
SELECT * FROM spectra_core.file_upload_session
WHERE owner_user_id = #{ownerUserId} AND content_sha256 = #{sha256} AND size = #{size}
  AND status IN ('UPLOADING', 'VERIFYING') AND expires_at > #{now}
  AND last_activity_at > #{idleBefore} AND deleted IS NULL
ORDER BY created_at DESC
LIMIT 1

SELECT * FROM spectra_core.file_upload_session
WHERE status IN ('FAILED', 'CANCELED', 'EXPIRED', 'CLEANED') AND deleted IS NULL
  AND next_cleanup_at IS NOT NULL AND next_cleanup_at <= #{now}
ORDER BY next_cleanup_at
LIMIT #{limit}
FOR UPDATE SKIP LOCKED

mapper.delete:
DELETE FROM spectra_core.file_upload_session
WHERE id = #{id} AND status = 'CLEANED'
  AND next_cleanup_at IS NOT NULL AND next_cleanup_at <= #{cutoff}
